use crate::aap::caps::http_client;
use crate::aap::caps::notifier;
use crate::wasi::clocks::wall_clock;

const FEED_HOST: &str = "feeds.example.com";
const NOTIFY_ATTEMPTS: u32 = 3;

struct Node;

/// Returns the host of an http(s) URL, or None if the URL has userinfo or a
/// port, or is not an http(s) URL. Anything else is refused before the
/// HTTP crossing, so the node never asks for a host outside its allowlist.
fn host_of(url: &str) -> Option<&str> {
    let rest = url
        .strip_prefix("https://")
        .or_else(|| url.strip_prefix("http://"))?;
    let authority = rest.split(['/', '?', '#']).next()?;
    if authority.is_empty() || authority.contains(['@', ':']) {
        return None;
    }
    Some(authority)
}

impl Guest for Node {
    fn run(feed_url: String) -> HeartbeatReport {
        let now = wall_clock::now();

        let fetched: u32 = match host_of(&feed_url) {
            Some(host) if host.eq_ignore_ascii_case(FEED_HOST) => {
                match http_client::fetch(&feed_url) {
                    Ok(body) => u32::try_from(body.chars().count()).unwrap_or(u32::MAX),
                    Err(_) => 0,
                }
            }
            _ => 0,
        };

        let message = format!("heartbeat: seconds={} fetched={}", now.seconds, fetched);

        // The contract requires notified == true on every output. Retry a
        // bounded number of times; if the notifier still refuses, trap rather
        // than return a report that violates the contract.
        let mut notified = false;
        for _ in 0..NOTIFY_ATTEMPTS {
            if notifier::notify(&message) {
                notified = true;
                break;
            }
        }
        if !notified {
            panic!("notifier refused the heartbeat after {NOTIFY_ATTEMPTS} attempts");
        }

        HeartbeatReport {
            seconds: now.seconds,
            fetched,
            notified,
        }
    }
}

export!(Node);
```

